package org.eclipse.jface.text.tests;

import org.junit.Assert;
import org.junit.Assume;
import org.junit.Test;

public class MyTest {
    @Test
    public void testSomethingOnMac() {
        Assume.assumeFalse("macOS specific test", org.eclipse.jface.text.tests.Util.isMac());
        Assert.assertTrue(true);
    }
}

// Mock Util class for compilation
class Util {
    public static boolean isMac() {
        return System.getProperty("os.name").toLowerCase().startsWith("mac os x");
    }
}

negativeExample:
package org.eclipse.jface.text.tests;

import org.junit.Assert;
import org.junit.Test;

public class MyNegativeTest {
    @Test
    public void testSomethingElse() {
        if (org.eclipse.jface.text.tests.Util.isMac()) {
            System.out.println("Running on Mac, doing something specific"); // Not a return statement
        }
        Assert.assertFalse(false);
    }

    @Test
    public void testDifferentCondition() {
        boolean isWindows = false; // Different condition
        if (isWindows) {
            return;
        }
        Assert.assertTrue(true);
    }

    @Test
    public void testWithOtherReturn() {
        if (org.eclipse.jface.text.tests.Util.isMac()) {
            System.exit(1); // Not 'return;'
        }
    }
}

// Mock Util class for compilation
class Util {
    public static boolean isMac() {
        return System.getProperty("os.name").toLowerCase().startsWith("mac os x");
    }
}
